public static final void check(X509Certificate[] chain) throws CertificateException {
    for (X509Certificate cert : chain) {
        try {
            checkCert(cert);
        } catch (CertificateException e) {
            throw new CertificateException(
                    "Unacceptable certificate: " + cert.getSubjectX500Principal(), e);
        }
    }
}

public void verify(final String host, final X509Certificate cert) throws SSLException {
    final HostNameType hostType = determineHostFormat(host);
    switch (hostType) {
    case IPv4:
        matchIPAddress(host, getSubjectAltNames(cert, SubjectName.IP));
        break;
    case IPv6:
        matchIPv6Address(host, getSubjectAltNames(cert, SubjectName.IP));
        break;
    default:
        final List<SubjectName> subjectAlts = getSubjectAltNames(cert, SubjectName.DNS);
        if (subjectAlts.isEmpty()) {
            matchCN(host, cert, this.publicSuffixMatcher);
        } else {
            matchDNSName(host, subjectAlts, this.publicSuffixMatcher);
        }
    }
}

static void matchIPAddress(final String host, final List<SubjectName> subjectAlts) throws SSLPeerUnverifiedException {
    for (final SubjectName subjectAlt : subjectAlts) {
        if (subjectAlt.getType() == SubjectName.IP) {
            if (host.equals(subjectAlt.getValue())) {
                return;
            }
        }
    }
    throw new SSLPeerUnverifiedException("Certificate for <" + host + "> doesn't match any "
            + "of the subject alternative names: " + subjectAlts);
}

static void matchIPv6Address(final String host, final List<SubjectName> subjectAlts) throws SSLPeerUnverifiedException {
    final String normalisedHost = normaliseAddress(host);
    for (final SubjectName subjectAlt : subjectAlts) {
        if (subjectAlt.getType() == SubjectName.IP) {
            final String normalizedSubjectAlt = normaliseAddress(subjectAlt.getValue());
            if (normalisedHost.equals(normalizedSubjectAlt)) {
                return;
            }
        }
    }
    throw new SSLPeerUnverifiedException("Certificate for <" + host + "> doesn't match any "
            + "of the subject alternative names: " + subjectAlts);
}

static void matchDNSName(final String host, final List<SubjectName> subjectAlts,
                         final PublicSuffixMatcher publicSuffixMatcher) throws SSLPeerUnverifiedException {
    final String normalizedHost = DnsUtils.normalizeUnicode(host);
    for (final SubjectName subjectAlt : subjectAlts) {
        if (subjectAlt.getType() == SubjectName.DNS) {
            final String normalizedSubjectAlt = DnsUtils.normalizeUnicode(subjectAlt.getValue());
            if (matchIdentity(normalizedHost, normalizedSubjectAlt, publicSuffixMatcher, true)) {
                return;
            }
        }
    }
    throw new SSLPeerUnverifiedException("Certificate for <" + host + "> doesn't match any "
            + "of the subject alternative names: " + subjectAlts);
}

static void matchCN(final String host, final X509Certificate cert,
                    final PublicSuffixMatcher publicSuffixMatcher) throws SSLException {
    final X500Principal subjectPrincipal = cert.getSubjectX500Principal();
    final String cn = extractCN(subjectPrincipal.getName(X500Principal.RFC2253));
    if (cn == null) {
        throw new SSLPeerUnverifiedException("Certificate subject for <" + host + "> doesn't contain "
                + "a common name and does not have alternative names");
    }
    final String normalizedHost = DnsUtils.normalizeUnicode(host);
    final String normalizedCn = DnsUtils.normalizeUnicode(cn);
    if (!matchIdentity(normalizedHost, normalizedCn, publicSuffixMatcher, true)) {
        throw new SSLPeerUnverifiedException("Certificate for <" + host + "> doesn't match "
                + "common name of the certificate subject: " + cn);
    }
}

private void checkPins(List<X509Certificate> chain) throws CertificateException {
    PinSet pinSet = mNetworkSecurityConfig.getPins();
    if (pinSet.pins.isEmpty()
            || System.currentTimeMillis() > pinSet.expirationTime
            || !isPinningEnforced(chain)) {
        return;
    }
    Set<String> pinAlgorithms = pinSet.getPinAlgorithms();
    Map<String, MessageDigest> digestMap = new ArrayMap<String, MessageDigest>(
            pinAlgorithms.size());
    for (int i = chain.size() - 1; i >= 0 ; i--) {
        X509Certificate cert = chain.get(i);
        byte[] encodedSPKI = cert.getPublicKey().getEncoded();
        for (String algorithm : pinAlgorithms) {
            MessageDigest md = digestMap.get(algorithm);
            if (md == null) {
                try {
                    md = MessageDigest.getInstance(algorithm);
                } catch (GeneralSecurityException e) {
                    throw new RuntimeException(e);
                }
                digestMap.put(algorithm, md);
            }
            if (pinSet.pins.contains(new Pin(algorithm, md.digest(encodedSPKI)))) {
                return;
            }
        }
    }
    throw new CertificateException("Pin verification failed");
}

private boolean isPinningEnforced(List<X509Certificate> chain) throws CertificateException {
    if (chain.isEmpty()) {
        return false;
    }
    X509Certificate anchorCert = chain.get(chain.size() - 1);
    TrustAnchor chainAnchor =
            mNetworkSecurityConfig.findTrustAnchorBySubjectAndPublicKey(anchorCert);
    if (chainAnchor == null) {
        throw new CertificateException("Trusted chain does not end in a TrustAnchor");
    }
    return !chainAnchor.overridesPins;
}

public List<X509Certificate> checkServerTrusted(X509Certificate[] certs, String authType,
        String host) throws CertificateException {
    List<X509Certificate> trustedChain = mDelegate.checkServerTrusted(certs, authType, host);
    checkPins(trustedChain);
    return trustedChain;
}

public void checkServerTrusted(X509Certificate[] certificates, String authType) throws CertificateException {
    if (!isKnownServer(certificates[0])) {
        certificates[0].checkValidity();
        standardTrustManager.checkServerTrusted(certificates, authType);
    }
}

public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {
    throw new CertificateException("Client certificates not supported!");
}

if (systemTrustManager != null) {
    ((X509TrustManager) systemTrustManager).checkServerTrusted(chain, authType);
}

for (X509Certificate certificate : chain) {
    if (isValidPin(certificate)) {
        return;
    }
}
throw new CertificateException("No valid pins found in chain!");

private boolean isValidPin(X509Certificate certificate) throws CertificateException {
    try {
        final MessageDigest digest = MessageDigest.getInstance("SHA1");
        final byte[] spki          = certificate.getPublicKey().getEncoded();
        final byte[] pin           = digest.digest(spki);
        for (byte[] validPin : this.pins) {
            if (MessageDigest.isEqual(pin, validPin)) return true;
        }
        return false;
    } catch (NoSuchAlgorithmException nsae) {
        throw new CertificateException(nsae);
    }
}

private TrustManager[] getTrustManagers(KeyStore store) throws GeneralSecurityException {
    String tmfAlgorithm = TrustManagerFactory.getDefaultAlgorithm();
    TrustManagerFactory tmf = TrustManagerFactory.getInstance(tmfAlgorithm);
    tmf.init(store);
    return tmf.getTrustManagers();
}
